// All workshop lessons and guided solutions are intentionally written in English.
// Challenges are completed in the learner's local VS Code environment.
const challenge = (title, task, example, solution, hint, walkthrough, level = 'Beginner') => ({ title, task, example, solution: solution.trim(), hint, walkthrough, level, language: /^# (Linux\/macOS terminal|Terminal commands)/.test(solution.trim()) ? 'terminal' : 'python' });
const stage = (id, title, subtitle, concept, snippet, takeaways, mistakes, challenges, category = 'core') => ({ id, title, subtitle, concept, snippet: snippet.trim(), takeaways, mistakes, challenges, category });

export const stages = [
  stage('variables', 'Variables & types', 'Start with values, names, input, and readable output.',
    'A variable is a name pointing to a value. Python discovers a value’s type at runtime: int, float, str, bool, or None. Use descriptive snake_case names, convert user input explicitly, and explore values with print() and type().',
    `name = "Alex"       # str\nage = 19            # int\nheight = 1.78       # float\nis_student = True  # bool\nprint(f"{name} is {age} years old")`,
    ['Use = for assignment, == for comparison.','input() always returns a string.','Use int() or float() to convert numerical text.','Use f-strings for readable output.'],
    'Avoid mixing a string and an integer with +. Convert first, or use an f-string.',[
      challenge('Personal introduction','Ask for a name, age, and city. Print one friendly sentence containing all three values.',`Input: Maya, 21, Rabat → "Maya is 21 years old and lives in Rabat."`, `name = input("Name: ")\nage = int(input("Age: "))\ncity = input("City: ")\nprint(f"{name} is {age} years old and lives in {city}.")`, 'Build the final sentence with an f-string.', ['Read three inputs and store them in descriptively named variables.','Convert the age to int to make it usable for calculations.','Interpolate the variables in an f-string.']),
      challenge('Temperature converter','Ask for a temperature in Celsius and display its Fahrenheit equivalent. Use F = C × 9/5 + 32.',`Input: 20 → Output: 68.0°F`, `celsius = float(input("Celsius: "))\nfahrenheit = celsius * 9 / 5 + 32\nprint(f"{fahrenheit}°F")`, 'Use float() so decimal temperatures work.', ['Read the Celsius value as float.','Apply the formula in the correct arithmetic order.','Display the calculated result.']),
      challenge('Seconds to minutes','Given a duration in seconds, calculate how many whole minutes and remaining seconds it contains.',`Input: 137 → Output: 2 minutes and 17 seconds`, `duration = int(input("Seconds: "))\nminutes = duration // 60\nseconds = duration % 60\nprint(f"{minutes} minutes and {seconds} seconds")`, 'Use // and % rather than ordinary division.', ['Divide by 60 using // for complete minutes.','Use % 60 to get the remainder.','Show both parts in one sentence.']),
      challenge('Swap two values','Read two values and swap them without losing either value.',`Before: first = "tea", second = "coffee" → After: coffee, tea`, `first = input("First: ")\nsecond = input("Second: ")\nfirst, second = second, first\nprint(first, second)`, 'Python supports simultaneous assignment.', ['Read the two values.','Use tuple unpacking to swap them in one statement.','Print both new values.']),
      challenge('Receipt total','Read a unit price and a quantity. Display the total with exactly two decimal places.',`Price: 12.5, Quantity: 3 → Total: 37.50`, `price = float(input("Price: "))\nquantity = int(input("Quantity: "))\ntotal = price * quantity\nprint(f"Total: {total:.2f}")`, 'Format currency-like decimals with :.2f.', ['Convert money to float and quantity to int for this introductory example.','Multiply price by quantity.','Format the output to two decimal places. For production money handling, learn decimal.Decimal.']),
      challenge('Type detective','Create one integer, one float, one string, one boolean and None. Print each value and its type.',`Output includes: <class 'int'> and <class 'NoneType'>`, `values = [7, 3.14, "Python", False, None]\nfor value in values:\n    print(value, type(value))`, 'The built-in type() function shows the type of a value.', ['Create five distinct kinds of values.','Group them in a list for iteration.','Pass each item to type().'])
    ]),
  stage('operators','Operators','Understand arithmetic, comparison, assignment, and boolean expressions.',
    'Operators transform values or compare them. Learn addition, division, integer division, modulo, exponentiation, augmented assignments, and comparison operators. Python uses and, or, not for boolean logic.',
    `print(17 // 5)      # 3\nprint(17 % 5)       # 2\nprint(2 ** 4)       # 16\nprint(5 != 3 and 7 >= 7)  # True`,
    ['// gives floor division; % gives a remainder.','** means exponentiation.','and / or short-circuit left to right.','Python comparisons can be chained: 0 < n < 10.'],
    'Do not confuse / with //, and do not use && or || from JavaScript.',[
      challenge('Even or odd','Read an integer and print whether it is even or odd using modulo.',`Input: 13 → Odd`, `number = int(input("Number: "))\nprint("Even" if number % 2 == 0 else "Odd")`, 'A number is even when its remainder divided by 2 is zero.', ['Use % 2 to calculate the remainder.','Compare the remainder with zero.','Choose a readable output.']),
      challenge('Simple interest','Ask for principal, annual interest rate (percentage), and number of years. Calculate simple interest.',`1000 at 5% for 2 years → 100 interest`, `principal = float(input("Principal: "))\nrate = float(input("Annual rate (%): "))\nyears = float(input("Years: "))\ninterest = principal * rate * years / 100\nprint(f"Interest: {interest:.2f}")`, 'Simple interest equals principal × rate × time / 100.', ['Read three numerical values.','Use the percentage formula.','Format the answer to two decimal places.']),
      challenge('Compare two numbers','Read two integers and say whether the first is greater, smaller, or equal to the second.',`Input: 9, 4 → "First is greater"`, `a = int(input("First: "))\nb = int(input("Second: "))\nif a > b:\n    print("First is greater")\nelif a < b:\n    print("First is smaller")\nelse:\n    print("Both are equal")`, 'There are three cases: >, < and ==.', ['Check the > case.','Otherwise check <.','If neither is true, equality remains.']),
      challenge('Shopping discount','Calculate the total after a percentage discount. Then compare it to a 100-unit budget.',`Price 150, discount 20% → Final 120, over budget`, `price = float(input("Price: "))\ndiscount = float(input("Discount (%): "))\nfinal_price = price * (1 - discount / 100)\nprint(f"Final: {final_price:.2f}")\nprint("Within budget" if final_price <= 100 else "Over budget")`, 'A 20% discount means multiplying by (1 - 0.20).', ['Convert the percentage to a fraction.','Calculate the price after reduction.','Compare the result with the budget.']),
      challenge('Three-digit extractor','Read a positive three-digit integer and output its hundreds, tens, and units digits separately.',`Input: 482 → 4, 8, 2`, `n = int(input("Three-digit number: "))\nhundreds = n // 100\ntens = (n // 10) % 10\nunits = n % 10\nprint(hundreds, tens, units)`, 'Use integer division to move digits and modulo to keep the last digit.', ['Divide by 100 for hundreds.','Divide by 10 then take % 10 for tens.','Use % 10 for the units digit.']),
      challenge('Leap-year rule','Determine if a year is a leap year: divisible by 4, except centuries must also be divisible by 400.',`2000 → True; 1900 → False; 2024 → True`, `year = int(input("Year: "))\nleap = year % 400 == 0 or (year % 4 == 0 and year % 100 != 0)\nprint(leap)`, 'Combine or and and with parentheses.', ['A multiple of 400 is always a leap year.','Otherwise a year needs divisibility by 4 but not by 100.','Combine both conditions.'], 'Intermediate')
    ]),
  stage('conditions','Conditions','Teach your programs to make decisions with if, elif, and else.',
    'Conditional branches execute only when their condition is true. Python uses indentation to define a block, not curly braces. Each if/elif/else chain selects at most one branch.',
    `score = 78\nif score >= 90:\n    print("Excellent")\nelif score >= 60:\n    print("Passed")\nelse:\n    print("Try again")`,
    ['Indent blocks consistently using four spaces.','Order elif cases carefully.','Boolean expressions determine the branch.','Use else for remaining cases.'],
    'A broad condition placed before a specific one can make a later branch unreachable.',[
      challenge('Grade classifier','Read a score from 0 to 100 and print A (90+), B (80+), C (70+), D (60+), or F.',`85 → B`, `score = int(input("Score: "))\nif score >= 90:\n    print("A")\nelif score >= 80:\n    print("B")\nelif score >= 70:\n    print("C")\nelif score >= 60:\n    print("D")\nelse:\n    print("F")`, 'Test from the highest threshold down.', ['Start with >= 90.','Add descending elif branches.','Handle remaining scores with else.']),
      challenge('Ticket pricing','Children under 12 pay 5, adults under 65 pay 12, and seniors pay 8. Read age and print the ticket price.',`Age 70 → 8`, `age = int(input("Age: "))\nif age < 12:\n    price = 5\nelif age < 65:\n    price = 12\nelse:\n    price = 8\nprint(price)`, 'An elif only runs when preceding conditions were false.', ['Check the youngest age range.','Check adults up to 64.','Handle seniors in else.']),
      challenge('Positive, negative, or zero','Read a number and classify its sign.',`-4 → Negative`, `n = float(input("Number: "))\nif n > 0:\n    print("Positive")\nelif n < 0:\n    print("Negative")\nelse:\n    print("Zero")`, 'Check two strict inequalities, then else.', ['Compare with zero for positive.','Compare with zero for negative.','Zero is the only remaining possibility.']),
      challenge('Largest of three','Read three different integers and print the largest without calling max().',`7, 12, 3 → 12`, `a = int(input("A: "))\nb = int(input("B: "))\nc = int(input("C: "))\nif a >= b and a >= c:\n    print(a)\nelif b >= a and b >= c:\n    print(b)\nelse:\n    print(c)`, 'A candidate must be at least as large as both others.', ['Check whether a beats b and c.','If not, check b against both.','The remaining maximum is c.']),
      challenge('Password length gate','Read a password and display Short if it has fewer than 8 characters, Good if 8–15, and Long otherwise.',`"secure123" → Good`, `password = input("Password: ")\nlength = len(password)\nif length < 8:\n    print("Short")\nelif length <= 15:\n    print("Good")\nelse:\n    print("Long")`, 'Use len() to count characters.', ['Get the string length.','Compare it with the lower threshold.','Use elif for the middle range.']),
      challenge('Basic calculator','Read two numbers and an operator (+, -, *, /). Perform the operation; reject division by zero and unknown operators.',`10 / 0 → Cannot divide by zero`, `a = float(input("A: "))\nop = input("Operator: ")\nb = float(input("B: "))\nif op == "+":\n    print(a + b)\nelif op == "-":\n    print(a - b)\nelif op == "*":\n    print(a * b)\nelif op == "/":\n    print("Cannot divide by zero" if b == 0 else a / b)\nelse:\n    print("Unknown operator")`, 'Test the operator first and guard the / case.', ['Read the numbers and operator.','Implement one branch per supported symbol.','Special-case division by zero and unsupported operators.'], 'Intermediate')
    ]),
  stage('advanced-conditions','Advanced conditions','Combine rules without making your logic difficult to read.',
    'Real requirements often have several conditions, validation rules, and boundaries. Break complicated expressions into named booleans, use membership tests, and recognize truthy/falsy values. Practice nested decisions only when they improve clarity.',
    `age = 20\nhas_ticket = True\nis_allowed = age >= 18 and has_ticket\nif is_allowed:\n    print("Welcome")`,
    ['Prefer clear named conditions.','Use in to test membership.','Use is None for identity checks with None.','Not every non-empty string represents True.'],
    'Avoid checking x == True when x is already a boolean; avoid using is for string or integer equality.',[
      challenge('Username rules','A username is valid if it is between 4 and 16 characters and has no spaces.',`"python_dev" → Valid; "a b" → Invalid`, `username = input("Username: ")\nvalid_length = 4 <= len(username) <= 16\nno_spaces = " " not in username\nprint("Valid" if valid_length and no_spaces else "Invalid")`, 'Use a chained comparison and the not in operator.', ['Check the length range.','Check whether a space is absent.','Require both rules at the same time.']),
      challenge('Triangle validator','Read three side lengths. Print Valid triangle only when every side is positive and each pair sums to more than the third.',`3, 4, 5 → Valid triangle`, `a, b, c = map(float, input("Three sides: ").split())\npositive = a > 0 and b > 0 and c > 0\ntriangle = a + b > c and a + c > b and b + c > a\nprint("Valid triangle" if positive and triangle else "Invalid triangle")`, 'You need all three triangle inequalities.', ['Verify positive sides.','Check every two sides against the third.','Combine both named booleans.'], 'Intermediate'),
      challenge('Access control','A user can access a resource if they are an admin or if they are an active member and their account is verified.',`admin=False, active=True, verified=True → Access granted`, `admin = False\nactive = True\nverified = True\nallowed = admin or (active and verified)\nprint("Access granted" if allowed else "Access denied")`, 'Parentheses make precedence readable.', ['Express the admin override.','Express the member requirements together.','Combine using or.']),
      challenge('Shipping calculator','Orders of 200 or more ship for free. Otherwise express shipping costs 25 and standard costs 10.',`Total 150, express=True → shipping 25`, `total = float(input("Order total: "))\nexpress = input("Express? (y/n): ").lower() == "y"\nif total >= 200:\n    shipping = 0\nelif express:\n    shipping = 25\nelse:\n    shipping = 10\nprint(shipping)`, 'Check free shipping first.', ['Check the total threshold.','Otherwise decide between express and standard.','Display the shipping fee.']),
      challenge('Date input guard','Read a day and month. Reject months outside 1–12 and days outside 1–31; do not attempt a full calendar validator.',`Month 13 → Invalid`, `day = int(input("Day: "))\nmonth = int(input("Month: "))\nvalid = 1 <= month <= 12 and 1 <= day <= 31\nprint("Valid range" if valid else "Invalid range")`, 'This is a range check, not a complete date validator.', ['Check the month bounds.','Check day bounds separately.','Combine the boolean checks.']),
      challenge('Valid IPv4 octet','Write a small program that reads one decimal octet and prints Valid when it contains digits and its numerical value is 0–255.',`"256" → Invalid; "42" → Valid`, `raw = input("Octet: ")\nvalid = raw.isdigit() and 0 <= int(raw) <= 255\nprint("Valid" if valid else "Invalid")`, 'Short-circuiting prevents int() running on non-digits.', ['Ensure the input consists only of digits.','Convert and check 0–255.','Combine with and to avoid bad conversion.'], 'Intermediate')
    ]),
  stage('loops','Loops','Repeat work with for, while, range, and counters.',
    'Use a for loop when iterating over a sequence or a range. Use while when repetition depends on a changing condition. The loop body is defined by indentation. Accumulators and counters help summarize many values.',
    `total = 0\nfor number in range(1, 6):\n    total += number\nprint(total)  # 15`,
    ['range(5) produces 0 through 4.','A while loop needs a condition that eventually becomes false.','Use += to accumulate values.','Loops can iterate directly over strings and lists.'],
    'Never write a while loop without making progress toward termination.',[
      challenge('Count from one to N','Read a positive integer N and print every number from 1 through N.',`N=4 → 1 2 3 4`, `n = int(input("N: "))\nfor i in range(1, n + 1):\n    print(i, end=" ")`, 'The upper boundary of range() is excluded.', ['Read N.','Generate integers with range(1, n + 1).','Print each number.']),
      challenge('Sum of even numbers','Read N and calculate the sum of all even numbers from 1 to N.',`N=10 → 30`, `n = int(input("N: "))\ntotal = 0\nfor i in range(2, n + 1, 2):\n    total += i\nprint(total)`, 'range() can step by two.', ['Initialize total at zero.','Iterate over even numbers only.','Add each number to the total.']),
      challenge('Multiplication table','Ask for an integer and print its multiplication table from 1 to 10.',`N=3 → 3 × 1 = 3 ... 3 × 10 = 30`, `n = int(input("N: "))\nfor i in range(1, 11):\n    print(f"{n} × {i} = {n * i}")`, 'Repeat ten times with i in range(1, 11).', ['Read the multiplicand.','Use a loop for multipliers 1–10.','Build formatted output for every line.']),
      challenge('Factorial','Calculate N! for a non-negative integer. Remember 0! = 1.',`N=5 → 120`, `n = int(input("N: "))\nresult = 1\nfor i in range(2, n + 1):\n    result *= i\nprint(result)`, 'Start the accumulator at 1 for multiplication.', ['Initialize the product as one.','Multiply by every integer from 2 through N.','Print the product.']),
      challenge('Digit counter','Read a non-negative integer and count its digits using a while loop, including zero as one digit.',`N=5072 → 4`, `n = int(input("Non-negative integer: "))\ncount = 1 if n == 0 else 0\nwhile n > 0:\n    count += 1\n    n //= 10\nprint(count)`, 'Each // 10 removes the last digit.', ['Handle zero as a special case.','Remove one digit on every iteration.','Count how many iterations happen.']),
      challenge('Number guessing loop','Keep reading guesses until the player guesses the fixed secret number 7; then print the attempt count.',`Guesses: 2, 8, 7 → 3 attempts`, `secret = 7\nattempts = 0\nwhile True:\n    guess = int(input("Guess: "))\n    attempts += 1\n    if guess == secret:\n        break\nprint(f"Solved in {attempts} attempts")`, 'Use break when the player succeeds.', ['Initialize an attempt counter.','Repeat reading guesses.','Increment for each attempt and break on a match.'], 'Intermediate')
    ]),
  stage('advanced-loops','Advanced loops','Work with nested loops, break, continue, and patterns.',
    'Nested loops are useful for grids and comparing pairs. break exits the closest loop, continue skips the remainder of the current iteration, and enumerate() gives an index together with an item.',
    `for row in range(1, 4):\n    for col in range(1, 4):\n        print(row * col, end=" ")\n    print()`,
    ['Understand the inner loop runs fully per outer iteration.','break exits the nearest loop.','continue skips to the next iteration.','Nested loops can cost O(n²).'],
    'Do not use unnecessary nested loops where a single traversal would work.',[
      challenge('Star triangle','Read N and print a right triangle of stars using nested loops.',`N=3 → * / ** / *** (on separate lines)`, `n = int(input("Rows: "))\nfor row in range(1, n + 1):\n    for col in range(row):\n        print("*", end="")\n    print()`, 'The number of stars on each line is the row number.', ['Use the outer loop for rows.','Use the inner loop to print row stars.','Add a newline after each row.']),
      challenge('Skip multiples of three','Print numbers 1 through 20, excluding multiples of three.',`1 2 4 5 7 ... 20`, `for n in range(1, 21):\n    if n % 3 == 0:\n        continue\n    print(n, end=" ")`, 'continue skips the current loop iteration.', ['Iterate over the desired range.','Check n % 3 == 0.','Skip those numbers and print the rest.']),
      challenge('First repeated character','Find the first character that appears twice while reading a string from left to right. Print None if no repeat exists.',`"abcbad" → b`, `text = input("Text: ")\nseen = set()\nfor char in text:\n    if char in seen:\n        print(char)\n        break\n    seen.add(char)\nelse:\n    print("None")`, 'Maintain a set of already-seen characters.', ['Create an empty set.','On each character, check whether it was already seen.','Break on the first repeat; for/else handles no repeats.'], 'Intermediate'),
      challenge('Grid coordinates','Print all ordered pairs (row, column) for a grid of R rows and C columns, counting from zero.',`R=2, C=3 → (0,0) (0,1) (0,2) (1,0) (1,1) (1,2)`, `rows = int(input("Rows: "))\ncols = int(input("Columns: "))\nfor r in range(rows):\n    for c in range(cols):\n        print((r, c), end=" ")`, 'The inner loop represents columns.', ['Loop across rows.','Inside each row, loop over columns.','Print each coordinate pair.']),
      challenge('Prime checker','Read an integer greater than 1 and determine whether it is prime by checking divisors up to its square root.',`29 → Prime; 21 → Not prime`, `n = int(input("N: "))\nif n < 2:\n    print("Not prime")\nelse:\n    prime = True\n    for divisor in range(2, int(n ** 0.5) + 1):\n        if n % divisor == 0:\n            prime = False\n            break\n    print("Prime" if prime else "Not prime")`, 'Any composite integer has a divisor no larger than its square root.', ['Reject values below two.','Try divisors from two through sqrt(n).','Break on an exact divisor.'], 'Intermediate'),
      challenge('Multiplication grid','Print a multiplication grid from 1 to N with each cell right-aligned to width 4.',`N=3 → 1 2 3 / 2 4 6 / 3 6 9`, `n = int(input("N: "))\nfor i in range(1, n + 1):\n    for j in range(1, n + 1):\n        print(f"{i * j:4}", end="")\n    print()`, 'Use f"{value:4}" for four-character alignment.', ['Create outer and inner loops.','Multiply their indexes.','Print aligned cells and then a newline.'], 'Intermediate')
    ]),
  stage('lists','Lists & tuples','Store multiple items, update them, slice them, and iterate over them.',
    'A list is a mutable, ordered collection. A tuple is an immutable, ordered collection. Learn indexes starting at zero, slices, append(), remove(), sorted(), membership, and comprehensions.',
    `scores = [12, 16, 9]\nscores.append(18)\nprint(scores[0], scores[-1])\nprint(scores[1:3])\nfixed = (10, 20)`,
    ['Lists can change; tuples cannot.','Index -1 refers to the final element.','Slices exclude the end index.','sorted(items) returns a new list.'],
    'Do not modify a list as you iterate over it unless you carefully handle index changes.',[
      challenge('List statistics','Read comma-separated integers and print their sum, minimum, maximum, and average.',`2,4,6 → sum=12 min=2 max=6 average=4.0`, `numbers = [int(x) for x in input("Numbers: ").split(",")]\nprint("sum=", sum(numbers))\nprint("min=", min(numbers))\nprint("max=", max(numbers))\nprint("average=", sum(numbers) / len(numbers))`, 'Convert strings from split(",") using a comprehension.', ['Split the input at commas.','Convert every element to int.','Calculate statistics using built-in functions.']),
      challenge('Remove duplicates in order','Given a list, build a new list containing each distinct value once, preserving its first appearance.',`[3,1,3,2,1] → [3,1,2]`, `values = [3, 1, 3, 2, 1]\nunique = []\nfor value in values:\n    if value not in unique:\n        unique.append(value)\nprint(unique)`, 'Do not convert directly to set if you need to demonstrate stable ordering.', ['Create an empty list.','Iterate across the original values.','Append only values not already present.'], 'Intermediate'),
      challenge('Second largest distinct number','Write a function that returns the second largest distinct value or None if fewer than two distinct values exist.',`[4,9,9,2] → 4`, `def second_largest(numbers):\n    distinct = sorted(set(numbers), reverse=True)\n    return distinct[1] if len(distinct) >= 2 else None\n\nprint(second_largest([4, 9, 9, 2]))`, 'Remove duplicates before selecting the second element.', ['Convert to a set of distinct values.','Sort from largest to smallest.','Guard the case with fewer than two values.'], 'Intermediate'),
      challenge('Rotate a list','Write rotate_right(items, k) that shifts a list to the right by k positions without changing its length.',`[1,2,3,4], k=1 → [4,1,2,3]`, `def rotate_right(items, k):\n    if not items:\n        return []\n    k %= len(items)\n    return items[-k:] + items[:-k] if k else items[:]`, 'Use list slices, but handle an empty list and k=0.', ['Normalize k using the length.','Split the list into the last k and the rest.','Join both pieces in reverse order.'], 'Intermediate'),
      challenge('Matrix row totals','Given a 2D list, calculate the total of each row.',`[[1,2],[3,4]] → [3,7]`, `matrix = [[1, 2], [3, 4]]\nrow_totals = [sum(row) for row in matrix]\nprint(row_totals)`, 'A matrix is just a list of lists.', ['Iterate over each row.','Sum the row.','Collect all sums in a new list.']),
      challenge('Tuple unpacking','Given a list of (name, score) pairs, print every name with its score. Print the name of the highest scorer.',`[("Ava", 12), ("Noah", 18)] → Noah`, `records = [("Ava", 12), ("Noah", 18)]\nfor name, score in records:\n    print(name, score)\nbest = max(records, key=lambda item: item[1])\nprint("Top:", best[0])`, 'Use for name, score in records.', ['Unpack each tuple while iterating.','Use max with a key selecting the score.','Print the best student name.'], 'Intermediate')
    ]),
  stage('strings','Strings','Search, slice, normalize, and process text safely.',
    'Strings are immutable sequences of characters. Use slicing, split(), join(), strip(), lower(), replace(), count(), and character methods. Loop through strings to solve real text-processing problems.',
    `message = "  Hello, Python!  "\nclean = message.strip().lower()\nwords = clean.split()\nprint("-".join(words))`,
    ['Strings cannot be modified in place.','strip() removes surrounding whitespace.','split() turns a string into parts; join() connects them.','Unicode characters are not always a single visible glyph.'],
    'Do not call .sort() on a string. Strings are immutable; use sorted() to obtain characters.',[
      challenge('Reverse text','Ask for a line of text and display its characters in reverse order.',`"python" → "nohtyp"`, `text = input("Text: ")\nprint(text[::-1])`, 'Use slicing with a negative step.', ['Read the string.','Slice the entire string with step -1.','Print the reversed result.']),
      challenge('Vowel counter','Count the number of English vowels (a,e,i,o,u) in a string, case-insensitively.',`"Education" → 5`, `text = input("Text: ").lower()\ncount = sum(1 for ch in text if ch in "aeiou")\nprint(count)`, 'Normalize to lowercase first.', ['Convert input to lowercase.','Check each character against the vowel set.','Increment or sum a count.']),
      challenge('Palindrome ignoring spaces','Test whether a string reads the same forward and backward, ignoring spaces and case.',`"Never odd or even" → True`, `text = input("Text: ")\nclean = "".join(text.lower().split())\nprint(clean == clean[::-1])`, 'Normalize the text before comparing it to its reverse.', ['Convert to lowercase and remove whitespace.','Reverse the normalized string.','Compare the two versions.']),
      challenge('Word frequency','Count how many times each word appears in a sentence, ignoring case. Print the resulting dictionary.',`"Red blue red" → {'red': 2, 'blue': 1}`, `sentence = input("Sentence: ").lower()\ncounts = {}\nfor word in sentence.split():\n    counts[word] = counts.get(word, 0) + 1\nprint(counts)`, 'A dictionary can store one counter per distinct word.', ['Split normalized text into words.','Increment a dictionary entry per word.','Print the mapping.'], 'Intermediate'),
      challenge('Simple email check','Check whether a string has exactly one @, at least one dot after it, and nonempty text before and after the @. This is a learning exercise, not full email validation.',`"a@b.com" → True; "@b.com" → False`, `email = input("Email: ")\nparts = email.split("@")\nvalid = (len(parts) == 2 and bool(parts[0]) and bool(parts[1])\n         and "." in parts[1] and not parts[1].startswith("."))\nprint(valid)`, 'Use split("@") and verify the resulting pieces.', ['Require exactly one @.','Require nonempty local and domain parts.','Check that the domain contains a dot.'], 'Intermediate'),
      challenge('Run-length encoding','Compress consecutive repeated characters as a character followed by its count.',`"aaabbc" → "a3b2c1"`, `def compress(text):\n    if not text:\n        return ""\n    result = []\n    count = 1\n    for i in range(1, len(text) + 1):\n        if i < len(text) and text[i] == text[i - 1]:\n            count += 1\n        else:\n            result.append(text[i - 1] + str(count))\n            count = 1\n    return "".join(result)\n\nprint(compress("aaabbc"))`, 'Track the current run; flush it when the next character is different.', ['Handle an empty string.','Count consecutive identical characters.','Add each completed run to the result.'], 'Intermediate')
    ]),
  stage('functions','Functions','Package logic into reusable, testable units.',
    'Functions accept parameters and can return results. Use def, return, default arguments, keyword arguments, and docstrings. Keep one clear responsibility per function. Returning a value is different from printing it.',
    `def calculate_total(price, qty=1):\n    """Return the cost before tax."""\n    return price * qty\n\nprint(calculate_total(12, qty=3))`,
    ['return gives the result back to the caller.','A function stops when return runs.','Use defaults only for optional arguments.','Prefer pure functions when practical.'],
    'Do not use a mutable list or dictionary as a default argument unless you deliberately want shared state.',[
      challenge('Reusable rectangle area','Define rectangle_area(width, height) that returns the area of the rectangle.',`rectangle_area(4, 7) → 28`, `def rectangle_area(width, height):\n    return width * height\n\nprint(rectangle_area(4, 7))`, 'The formula is width × height.', ['Create a function with two parameters.','Return the product instead of printing inside the function.','Call it with sample arguments.']),
      challenge('Safe average','Create average(numbers) that returns the arithmetic mean or None when the list is empty.',`average([10,20,30]) → 20.0; average([]) → None`, `def average(numbers):\n    if not numbers:\n        return None\n    return sum(numbers) / len(numbers)\n\nprint(average([10, 20, 30]))`, 'Handle the empty list before division.', ['Check for an empty list.','Use sum and len for a nonempty list.','Return the result.']),
      challenge('Prime function','Define is_prime(n) that returns a boolean and works for values below 2.',`is_prime(17) → True; is_prime(1) → False`, `def is_prime(n):\n    if n < 2:\n        return False\n    for divisor in range(2, int(n ** 0.5) + 1):\n        if n % divisor == 0:\n            return False\n    return True\n\nprint(is_prime(17))`, 'Return False early when finding a divisor.', ['Handle values below two.','Search for divisors only up to sqrt(n).','Return True when none are found.'], 'Intermediate'),
      challenge('Flexible greeting','Write greet(name, prefix="Hello") and return a greeting, supporting both positional and keyword arguments.',`greet("Sam") → "Hello, Sam!"; greet("Sam",prefix="Hi") → "Hi, Sam!"`, `def greet(name, prefix="Hello"):\n    return f"{prefix}, {name}!"\n\nprint(greet("Sam"))\nprint(greet("Sam", prefix="Hi"))`, 'Give the optional parameter a default value.', ['Place the required name first.','Provide a default value for prefix.','Return a formatted greeting.']),
      challenge('Factorial with recursion','Write factorial(n) recursively for non-negative integers. Raise ValueError for negative inputs.',`factorial(5) → 120`, `def factorial(n):\n    if n < 0:\n        raise ValueError("n must be non-negative")\n    if n <= 1:\n        return 1\n    return n * factorial(n - 1)\n\nprint(factorial(5))`, 'Every recursive function needs a base case.', ['Reject invalid negative inputs.','Return one for n=0 or n=1.','Reduce the problem to factorial(n-1).'], 'Intermediate'),
      challenge('Function composition','Write normalize_name(text) that strips outside spaces, collapses repeated internal spaces, and title-cases words.',`"   mARY   jane " → "Mary Jane"`, `def normalize_name(text):\n    words = text.strip().split()\n    return " ".join(word.capitalize() for word in words)\n\nprint(normalize_name("   mARY   jane "))`, 'split() without an argument treats consecutive whitespace as one separator.', ['Remove outside whitespace.','Split into words and capitalize each one.','Join with single spaces.'], 'Intermediate')
    ]),
  stage('dictionaries','Dictionaries & sets','Model structured data and look up values efficiently.',
    'Dictionaries map keys to values, making them useful for records, frequency counters, and indexes. Sets hold distinct hashable values. Learn get(), items(), keys(), values(), update(), and dictionary/set comprehensions.',
    `person = {"name": "Noah", "score": 18}\nprint(person.get("city", "Unknown"))\nfor key, value in person.items():\n    print(key, value)\nunique = set([1, 1, 2])`,
    ['Keys must be hashable; values may be any type.','get() avoids KeyError for missing keys.','Sets eliminate duplicates and support membership tests.','Dictionary iteration normally yields keys.'],
    'Do not index into a set or assume dictionary order gives you a sorted order.',[
      challenge('Student record','Create a dictionary with name, age, and grade. Update the grade and print a formatted summary.',`Alex, age 20, grade 17 → "Alex (20): 17"`, `student = {"name": "Alex", "age": 20, "grade": 14}\nstudent["grade"] = 17\nprint(f"{student['name']} ({student['age']}): {student['grade']}")`, 'Use student["grade"] = new_value.', ['Create a record with three keys.','Reassign the grade key.','Format the updated dictionary fields.']),
      challenge('Frequency counter','Define count_values(items), which returns a dictionary of frequencies.',`["a","b","a"] → {'a': 2, 'b': 1}`, `def count_values(items):\n    counts = {}\n    for item in items:\n        counts[item] = counts.get(item, 0) + 1\n    return counts\n\nprint(count_values(["a", "b", "a"]))`, 'Use dict.get(key, 0) for a missing key.', ['Start with an empty dictionary.','Increase each item’s count.','Return the frequency dictionary.']),
      challenge('Inventory changes','Maintain a product dictionary mapping names to quantities. Add stock for an existing item and insert a new item.',`{"pen": 3} + 2 pens + 5 notebooks → {"pen": 5, "notebook": 5}`, `inventory = {"pen": 3}\ninventory["pen"] = inventory.get("pen", 0) + 2\ninventory["notebook"] = inventory.get("notebook", 0) + 5\nprint(inventory)`, 'Use get() to support existing and new products.', ['Retrieve the old quantity or zero.','Add incoming stock.','Repeat for the new product.']),
      challenge('Shared interests','Given two sets of interests, calculate their intersection, union, and differences.',`{"python","web"} & {"python","data"} → {"python"}`, `a = {"python", "web"}\nb = {"python", "data"}\nprint("Shared:", a & b)\nprint("All:", a | b)\nprint("Only A:", a - b)`, 'Use &, | and - for set operations.', ['Create two sets.','Use intersection to find overlap.','Use union and difference for the other queries.']),
      challenge('Group scores by student','Given a list of (student, score) pairs, create a dictionary mapping each student to all of their scores.',`[("A",12),("B",15),("A",18)] → {'A':[12,18], 'B':[15]}`, `records = [("A", 12), ("B", 15), ("A", 18)]\ngroups = {}\nfor name, score in records:\n    groups.setdefault(name, []).append(score)\nprint(groups)`, 'setdefault(name, []) can create a new list for a new key.', ['Initialize an empty dictionary.','Create a list for each new student.','Append the score to that student’s list.'], 'Intermediate'),
      challenge('Top-selling product','Given a mapping from product names to sales counts, return the name with the highest count. Return None when the mapping is empty.',`{"pen": 8, "book": 13} → "book"`, `def best_seller(sales):\n    if not sales:\n        return None\n    return max(sales, key=sales.get)\n\nprint(best_seller({"pen": 8, "book": 13}))`, 'The key argument of max controls what is compared.', ['Handle an empty mapping.','Use max over dictionary keys.','Compare values using sales.get.'], 'Intermediate')
    ]),
  stage('search-sort','Searching & sorting','Find, order, and reason about collections.',
    'Searching is about locating a value; sorting puts values in order. Linear search works on arbitrary data. Binary search requires sorted input and repeatedly halves the remaining interval. Learn sorted(), list.sort(), key=, and basic complexity.',
    `names = ["Kai", "Ava", "Mia"]\nprint(sorted(names))\nprint(sorted(names, key=len))\nprint("Ava" in names)`,
    ['Linear search usually costs O(n).','Binary search costs O(log n) on sorted input.','sorted() returns a new list; sort() changes the existing list.','A key function controls sort criteria.'],
    'Binary search on an unsorted list is not correct.',[
      challenge('Linear search index','Implement linear_search(items, target) that returns the first matching index or -1.',`linear_search([4,7,4],4) → 0`, `def linear_search(items, target):\n    for index, item in enumerate(items):\n        if item == target:\n            return index\n    return -1\n\nprint(linear_search([4, 7, 4], 4))`, 'enumerate() gives indexes without a manual counter.', ['Iterate over indexes and values.','Return immediately when you find a match.','Return -1 after the loop when nothing matches.']),
      challenge('Sort people by age','Given a list of dictionaries with name and age, return a new list sorted by age ascending.',`[{name:"A", age:30}, {name:"B", age:20}] → B then A`, `people = [{"name": "A", "age": 30}, {"name": "B", "age": 20}]\nordered = sorted(people, key=lambda p: p["age"])\nprint(ordered)`, 'Use sorted(..., key=lambda person: person["age"]).', ['Keep the original list unchanged.','Use a key that extracts age.','Print the ordered list.']),
      challenge('Binary search','Implement binary_search(sorted_items, target). Return its index, or -1 if missing.',`binary_search([2,5,8,11],8) → 2`, `def binary_search(items, target):\n    left, right = 0, len(items) - 1\n    while left <= right:\n        mid = (left + right) // 2\n        if items[mid] == target:\n            return mid\n        if items[mid] < target:\n            left = mid + 1\n        else:\n            right = mid - 1\n    return -1\n\nprint(binary_search([2, 5, 8, 11], 8))`, 'Compare the middle element and discard half the interval.', ['Track left and right indexes.','Inspect the middle element.','Move one boundary until found or the interval is empty.'], 'Intermediate'),
      challenge('Find first occurrence','In a sorted list with duplicates, return the first index containing target, or -1.',`[1,2,2,2,5], target=2 → 1`, `def first_occurrence(items, target):\n    left, right = 0, len(items) - 1\n    answer = -1\n    while left <= right:\n        mid = (left + right) // 2\n        if items[mid] >= target:\n            if items[mid] == target:\n                answer = mid\n            right = mid - 1\n        else:\n            left = mid + 1\n    return answer\n\nprint(first_occurrence([1, 2, 2, 2, 5], 2))`, 'Save a match but keep searching left.', ['Use binary search boundaries.','Remember matching indexes instead of exiting.','Continue into the left half to find the first one.'], 'Advanced'),
      challenge('Selection sort','Implement selection_sort(numbers) without built-in sorting. Return a new sorted list.',`[5,2,4] → [2,4,5]`, `def selection_sort(numbers):\n    result = numbers[:] \n    for i in range(len(result)):\n        smallest = i\n        for j in range(i + 1, len(result)):\n            if result[j] < result[smallest]:\n                smallest = j\n        result[i], result[smallest] = result[smallest], result[i]\n    return result\n\nprint(selection_sort([5, 2, 4]))`, 'Place the smallest remaining value at each position.', ['Copy the input list.','Search for the smallest element in the remaining suffix.','Swap it into the current position.'], 'Intermediate'),
      challenge('Two-sum lookup','Given integers and target, return the two indexes whose values add to target, or None. Use a dictionary for efficient lookup.',`[2,7,11,15], target 9 → (0,1)`, `def two_sum(numbers, target):\n    seen = {}\n    for i, value in enumerate(numbers):\n        complement = target - value\n        if complement in seen:\n            return (seen[complement], i)\n        seen[value] = i\n    return None\n\nprint(two_sum([2, 7, 11, 15], 9))`, 'For each value, look for target - value in previously-seen numbers.', ['Keep a dictionary of number to index.','Check the required complement.','Store the current number if there was no match.'], 'Intermediate')
    ]),
  stage('files-json','Files & JSON','Persist information between runs with local files.',
    'The with statement safely closes files. Read text with encoding="utf-8", write with mode="w", and append with mode="a". Use json.dump/load for JSON files. Paths are resolved relative to the working directory unless explicitly absolute.',
    `from pathlib import Path\nimport json\npath = Path("notes.json")\npath.write_text(json.dumps({"done": True}), encoding="utf-8")\nprint(json.loads(path.read_text(encoding="utf-8")))`,
    ['Use with open(...) to manage file handles.','mode="w" overwrites existing file content.','JSON supports objects, arrays, strings, numbers, booleans, and null.','The pathlib module provides convenient path utilities.'],
    'Do not open important files with w until you understand that it replaces their contents.',[
      challenge('Daily notes','Create a notes.txt file, write three lines, then read and print the entire file.',`File content: Study / Practice / Review`, `from pathlib import Path\npath = Path("notes.txt")\npath.write_text("Study\\nPractice\\nReview\\n", encoding="utf-8")\nprint(path.read_text(encoding="utf-8"))`, 'Use pathlib.Path.write_text and read_text.', ['Create a Path pointing to the output file.','Write the lines separated by newline characters.','Read the contents back.']),
      challenge('Word count from file','Read story.txt and display the number of words separated by whitespace.',`"hello world again" → 3`, `from pathlib import Path\ntext = Path("story.txt").read_text(encoding="utf-8")\nprint(len(text.split()))`, 'split() without arguments handles spaces and newlines.', ['Read the file as text.','Split into whitespace-separated words.','Count using len().']),
      challenge('Save a contact as JSON','Create a contact dictionary and write it to contact.json with indentation. Load it and print the name.',`{"name":"Ava","phone":"123"} → Ava`, `import json\ncontact = {"name": "Ava", "phone": "123"}\nwith open("contact.json", "w", encoding="utf-8") as file:\n    json.dump(contact, file, indent=2)\nwith open("contact.json", encoding="utf-8") as file:\n    saved = json.load(file)\nprint(saved["name"])`, 'Use json.dump for files; json.dumps for strings.', ['Build a Python dictionary.','Write it as formatted JSON.','Read it back and access the name.']),
      challenge('Append to a log','Append a message to activity.log without deleting prior entries.',`Before: "Start" → after append: "Start\nLogin\n"`, `with open("activity.log", "a", encoding="utf-8") as file:\n    file.write("Login\\n")`, 'Use mode="a" rather than "w".', ['Open the log for appending.','Write a line followed by a newline.','Check that earlier lines remain intact.']),
      challenge('CSV expense summary','Read a simple expenses.csv file with columns category,amount and print the sum of the amounts using csv.DictReader.',`food,12.5 + bus,3 → 15.5`, `import csv\ntotal = 0.0\nwith open("expenses.csv", newline="", encoding="utf-8") as file:\n    for row in csv.DictReader(file):\n        total += float(row["amount"])\nprint(total)`, 'Use the standard csv module for structured CSV parsing.', ['Create a CSV reader with headers.','Convert amount values to floats.','Accumulate and print the total.'], 'Intermediate')
    ], 'extended'),
  stage('exceptions','Exceptions & debugging','Diagnose tracebacks and handle expected failures.',
    'Exceptions describe failures that occur during execution. Read tracebacks bottom-up to locate the problem. Catch specific exception types, use else/finally when useful, and raise meaningful errors for invalid inputs.',
    `try:\n    age = int(input("Age: "))\nexcept ValueError:\n    print("Please enter a number")\nelse:\n    print(f"Age: {age}")`,
    ['Distinguish syntax errors from runtime errors.','Catch only the errors you can meaningfully handle.','Use raise for invalid function arguments.','Debug with print(), breakpoints, and the VS Code debugger.'],
    'Avoid bare except: because it can hide bugs and interrupt signals.',[
      challenge('Safe integer reader','Write read_integer() that retries until the user enters a valid integer.',`Input: abc, 12 → 12`, `def read_integer():\n    while True:\n        try:\n            return int(input("Integer: "))\n        except ValueError:\n            print("Invalid input, try again")\n\nprint(read_integer())`, 'Use a while True loop with try/except.', ['Repeat until conversion succeeds.','Catch ValueError for invalid text.','Return from inside try once valid.']),
      challenge('Safe division function','Write divide(a, b) that raises ValueError with a helpful message when b equals zero.',`divide(10,0) → ValueError`, `def divide(a, b):\n    if b == 0:\n        raise ValueError("Denominator cannot be zero")\n    return a / b`, 'Raise an exception rather than returning an invented numerical answer.', ['Check the denominator.','Raise a specific error for the invalid case.','Return the quotient otherwise.']),
      challenge('Missing JSON file','Try to load data.json. When the file does not exist, use an empty list instead.',`Missing file → []`, `import json\ntry:\n    with open("data.json", encoding="utf-8") as file:\n        data = json.load(file)\nexcept FileNotFoundError:\n    data = []\nprint(data)`, 'Catch FileNotFoundError, not every possible exception.', ['Try to open and load the file.','Catch the missing-file case.','Initialize a safe default.']),
      challenge('Debug a broken average','A function divides sum(numbers) by len(numbers), but crashes on an empty list. Fix it and add three asserts.',`average([]) → None`, `def average(numbers):\n    if not numbers:\n        return None\n    return sum(numbers) / len(numbers)\n\nassert average([]) is None\nassert average([5]) == 5\nassert average([2, 4]) == 3`, 'Check edge cases before arithmetic.', ['Identify the ZeroDivisionError caused by len([]).','Handle empty input explicitly.','Add tests for zero, one, and multiple items.']),
      challenge('Debug with breakpoints','Use the VS Code debugger to find why this code adds the wrong value. Fix the bug and explain it.',`Bug: total =+ number (not +=)`, `numbers = [3, 5, 7]\ntotal = 0\nfor number in numbers:\n    total += number  # fixed: accumulate, do not reassign +number\nprint(total)  # 15`, 'Set a breakpoint inside the loop and inspect total after each iteration.', ['Run with a breakpoint at the assignment.','Notice =+ assigns the positive number rather than adding it.','Replace with += and rerun the check.'], 'Intermediate')
    ], 'extended'),
  stage('modules-env','Modules & environments','Set up real Python projects in VS Code.',
    'Modules are reusable .py files. A virtual environment isolates project dependencies. Use python -m venv .venv, activate it, select the interpreter in VS Code, and install packages with python -m pip. Organize bigger projects into modules and packages.',
    `# In the VS Code terminal\npython -m venv .venv\n# Linux/macOS: source .venv/bin/activate\n# Windows: .venv\\Scripts\\activate\npython -m pip --version\n# In Python: from math import sqrt`,
    ['Install Python separately from Node.js.','Create one virtual environment per project.','Keep .venv out of Git.','The if __name__ == "__main__" guard controls scripts.'],
    'Do not install dependencies into the wrong interpreter. Check python --version and python -m pip --version.',[
      challenge('Build a reusable module','Create math_tools.py with add(a,b) and multiply(a,b), then import and use them in main.py.',`main.py → 5 and 12`, `# math_tools.py\ndef add(a, b):\n    return a + b\n\ndef multiply(a, b):\n    return a * b\n\n# main.py (separate file)\nfrom math_tools import add, multiply\nprint(add(2, 3))\nprint(multiply(3, 4))`, 'Both files should be in the same project directory.', ['Create the math_tools.py module.','Define and return values from two functions.','Import from it in main.py and run main.py.']),
      challenge('Create a virtual environment','In VS Code, make a project folder, create .venv, activate it, and confirm which Python executable runs.',`python -m venv .venv`, `# Linux/macOS terminal\npython -m venv .venv\nsource .venv/bin/activate\npython -c "import sys; print(sys.executable)"\n\n# Windows PowerShell activation:\n# .venv\\Scripts\\Activate.ps1`, 'Select the .venv interpreter in VS Code with Python: Select Interpreter.', ['Open the project in VS Code.','Create and activate .venv in its terminal.','Print sys.executable to verify the active interpreter.']),
      challenge('Main entry point','Write a main() function and use the __name__ guard so importing the module does not execute the program.',`Running file → Ready; importing file → no output`, `def main():\n    print("Ready")\n\nif __name__ == "__main__":\n    main()`, 'Compare __name__ to the string "__main__".', ['Define the main function.','Call it only inside the guard.','Test running and importing the file.']),
      challenge('Install and record a package','Inside a venv, install requests and record project dependencies in requirements.txt.',`python -m pip install requests`, `# Terminal commands (not Python code)\npython -m pip install requests\npython -m pip freeze > requirements.txt\npython -m pip show requests`, 'Always invoke pip through the intended Python interpreter.', ['Activate the project environment.','Install requests using python -m pip.','Freeze installed packages for reproducibility.']),
      challenge('Folder organization','Build app.py, utils/text.py, utils/__init__.py and tests/test_text.py. Import a simple normalize_text function from utils.text.',`from utils.text import normalize_text`, `# utils/text.py\ndef normalize_text(value):\n    return " ".join(value.lower().split())\n\n# app.py\nfrom utils.text import normalize_text\nprint(normalize_text("  HELLO   WORLD "))\n\n# tests/test_text.py\nfrom utils.text import normalize_text\ndef test_normalize():\n    assert normalize_text("  A  B  ") == "a b"`, 'The example uses multiple files; create each file separately.', ['Create the package directory and files.','Define a helper inside utils/text.py.','Import it into app.py and write a test.'], 'Intermediate')
    ], 'extended'),
  stage('oop','Classes & objects','Model data and behavior together.',
    'A class describes objects with attributes and methods. __init__ initializes an instance; self refers to that instance. Practice small data models before inheritance. Prefer simple functions and dictionaries when a class would add needless complexity.',
    `class BankAccount:\n    def __init__(self, owner, balance=0):\n        self.owner = owner\n        self.balance = balance\n    def deposit(self, amount):\n        self.balance += amount\n\naccount = BankAccount("Ava")\naccount.deposit(50)`,
    ['self is the instance receiving the method call.','__init__ configures new objects.','Methods are functions bound to objects.','@dataclass can reduce boilerplate for data containers.'],
    'Do not confuse class attributes (shared) with instance attributes (per object).',[
      challenge('Rectangle class','Build Rectangle(width, height) with area() and perimeter() methods.',`Rectangle(3,4).area() → 12; perimeter() → 14`, `class Rectangle:\n    def __init__(self, width, height):\n        self.width = width\n        self.height = height\n\n    def area(self):\n        return self.width * self.height\n\n    def perimeter(self):\n        return 2 * (self.width + self.height)\n\nr = Rectangle(3, 4)\nprint(r.area(), r.perimeter())`, 'Store width and height using self.', ['Initialize instance attributes in __init__.','Implement both formulas as methods.','Create and test a rectangle.']),
      challenge('Bank account rules','Create a BankAccount with deposit and withdraw methods. Reject negative amounts and withdrawals above balance.',`Balance 100, withdraw 30 → 70`, `class BankAccount:\n    def __init__(self, balance=0):\n        self.balance = balance\n\n    def deposit(self, amount):\n        if amount <= 0:\n            raise ValueError("Amount must be positive")\n        self.balance += amount\n\n    def withdraw(self, amount):\n        if amount <= 0 or amount > self.balance:\n            raise ValueError("Invalid withdrawal")\n        self.balance -= amount\n\naccount = BankAccount(100)\naccount.withdraw(30)\nprint(account.balance)`, 'Check invariants before updating balance.', ['Store the account balance.','Validate the amount for deposits and withdrawals.','Only change balance after successful validation.'], 'Intermediate'),
      challenge('Student dataclass','Use @dataclass to create a Student with name, grades, and an average() method. Use field(default_factory=list).',`Student("Ava", [12,18]).average() → 15.0`, `from dataclasses import dataclass, field\n\n@dataclass\nclass Student:\n    name: str\n    grades: list[float] = field(default_factory=list)\n\n    def average(self):\n        return sum(self.grades) / len(self.grades) if self.grades else None\n\nprint(Student("Ava", [12, 18]).average())`, 'Use default_factory to avoid sharing one list across instances.', ['Decorate the class with @dataclass.','Use a safe default list factory.','Implement average() with an empty-list guard.'], 'Intermediate'),
      challenge('Simple inheritance','Create an Animal class with speak(), then Dog overriding it to return "Woof".',`Dog().speak() → "Woof"`, `class Animal:\n    def speak(self):\n        return "..."\n\nclass Dog(Animal):\n    def speak(self):\n        return "Woof"\n\nprint(Dog().speak())`, 'Use class Dog(Animal) to inherit.', ['Implement the base class method.','Create a subclass using parentheses.','Override the method with specialized behavior.']),
      challenge('Task manager objects','Model Task(title, done=False) and TaskList with add(), complete(index), and pending().',`Add "Study"; complete index 0 → pending=[]`, `from dataclasses import dataclass\n\n@dataclass\nclass Task:\n    title: str\n    done: bool = False\n\nclass TaskList:\n    def __init__(self):\n        self.tasks = []\n\n    def add(self, title):\n        self.tasks.append(Task(title))\n\n    def complete(self, index):\n        self.tasks[index].done = True\n\n    def pending(self):\n        return [task for task in self.tasks if not task.done]\n\nitems = TaskList()\nitems.add("Study")\nitems.complete(0)\nprint(items.pending())`, 'Keep tasks in an instance list and change the done attribute.', ['Define a Task data object.','Implement TaskList storing independent tasks.','Filter pending tasks by done status.'], 'Intermediate')
    ], 'extended'),
  stage('testing','Testing & clean code','Build confidence with repeatable tests and deliberate edge cases.',
    'Tests compare actual behavior with expected behavior. Start with assert, then learn pytest, fixtures, and parameterized tests. Improve code with descriptive names, type hints, docstrings, and small functions. A passing example is not proof of general correctness.',
    `def is_even(value: int) -> bool:\n    return value % 2 == 0\n\nassert is_even(4) is True\nassert is_even(5) is False`,
    ['Test normal cases, boundaries, and invalid inputs.','Use pytest for structured test suites.','Separate pure logic from input/output.','Type hints document expectations; they do not enforce runtime types.'],
    'Avoid making tests depend on random output or other hidden state without controlling it.',[
      challenge('Test a palindrome function','Write is_palindrome(text) and at least five tests, including empty text and mixed case.',`"Level" → True; "Python" → False`, `def is_palindrome(text):\n    cleaned = "".join(text.lower().split())\n    return cleaned == cleaned[::-1]\n\nassert is_palindrome("Level")\nassert is_palindrome("Never odd or even")\nassert is_palindrome("")\nassert not is_palindrome("Python")\nassert is_palindrome("a")`, 'Think of typical, boundary, and unusual inputs.', ['Write the function.','Add expected-true and expected-false tests.','Cover the empty and one-character strings.']),
      challenge('Write a pytest test file','Create calculator.py with add and subtract. Write tests/test_calculator.py with three tests and run pytest.',`python -m pytest`, `# calculator.py\ndef add(a, b):\n    return a + b\n\ndef subtract(a, b):\n    return a - b\n\n# tests/test_calculator.py\nfrom calculator import add, subtract\n\ndef test_add():\n    assert add(2, 3) == 5\n\ndef test_negative():\n    assert add(-3, 2) == -1\n\ndef test_subtract():\n    assert subtract(5, 2) == 3\n\n# terminal: python -m pip install pytest\n# terminal: python -m pytest`, 'Run tests from the project root with pytest installed in your venv.', ['Create the production module.','Put test_ functions in the tests directory.','Run python -m pytest and inspect results.']),
      challenge('Boundary cases for passwords','Define valid_password(password) as at least 8 characters including a digit and test boundary strings.',`"abcdefgh" → False; "abcdefg1" → True`, `def valid_password(password):\n    return len(password) >= 8 and any(ch.isdigit() for ch in password)\n\nassert not valid_password("1234567")\nassert not valid_password("abcdefgh")\nassert valid_password("abcdefg1")\nassert valid_password("longpassword42")`, 'Test exactly seven and exactly eight characters.', ['Implement the two conditions.','Test cases around length eight.','Test missing and present digits.']),
      challenge('Refactor a long function','Split a script that reads input, calculates the total, and prints a receipt into separate functions. Add tests for the calculation.',`calculate_total(10,3,0.2) → 36.0`, `def calculate_total(price, quantity, tax_rate):\n    return price * quantity * (1 + tax_rate)\n\ndef print_receipt(total):\n    print(f"Total: {total:.2f}")\n\ndef main():\n    price = float(input("Price: "))\n    quantity = int(input("Quantity: "))\n    print_receipt(calculate_total(price, quantity, 0.2))\n\nassert calculate_total(10, 3, 0.2) == 36.0\nif __name__ == "__main__":\n    main()`, 'Keep pure calculation separate from reading and printing.', ['Extract calculate_total().','Keep console input/output in main().','Test the calculation without needing input().'], 'Intermediate'),
      challenge('Type hints and docstrings','Add type hints and a docstring to a function that finds all positive even numbers from a list.',`filter_positive_even([-2,0,2,3,4]) → [2,4]`, `def filter_positive_even(numbers: list[int]) -> list[int]:\n    """Return positive, even integers from numbers."""\n    return [n for n in numbers if n > 0 and n % 2 == 0]\n\nassert filter_positive_even([-2, 0, 2, 3, 4]) == [2, 4]`, 'Annotate the parameter and return type with list[int].', ['Specify input and output types.','Explain the contract in a short docstring.','Filter and test the returned list.'])
    ], 'extended'),
  stage('data-bridge','Python for data','Prepare for NumPy, Pandas, and machine learning.',
    'Before AI libraries, learn clean data transformations using Python. Work with records, missing values, numeric summaries, comprehensions, and small pipelines. This section bridges general Python to a future dedicated NumPy/Pandas course.',
    `records = [{"name": "A", "score": 12}, {"name": "B", "score": 18}]\nvalid_scores = [r["score"] for r in records if r["score"] is not None]\nmean = sum(valid_scores) / len(valid_scores)\nprint(mean)`,
    ['Data cleaning means inspecting and transforming imperfect inputs.','Use None to represent missing values in small Python data examples.','Be careful not to divide by zero for empty datasets.','External NumPy/Pandas APIs are a separate learning stage.'],
    'Never silently replace all missing values with zero unless the problem defines that rule.',[
      challenge('Mean without missing values','Given numbers containing None values, calculate the mean of nonmissing values, or None when none exist.',`[10,None,20] → 15.0`, `def mean_present(values):\n    clean = [x for x in values if x is not None]\n    return sum(clean) / len(clean) if clean else None\n\nprint(mean_present([10, None, 20]))`, 'Filter None using is not None; zero is a valid number.', ['Filter absent values without excluding zero.','Check the cleaned list is nonempty.','Return its arithmetic mean.']),
      challenge('Normalize scores','Scale numeric scores from 0–100 to 0–1 with list comprehension.',`[0,50,100] → [0.0,0.5,1.0]`, `scores = [0, 50, 100]\nnormalized = [score / 100 for score in scores]\nprint(normalized)`, 'Divide each score by 100.', ['Iterate over each score.','Apply the same transformation.','Collect results in a new list.']),
      challenge('Filter records','Given records with name and active status, return only names of active users.',`[{"name":"A","active":True},{"name":"B","active":False}] → ["A"]`, `users = [{"name": "A", "active": True}, {"name": "B", "active": False}]\nactive_names = [u["name"] for u in users if u["active"]]\nprint(active_names)`, 'A list comprehension can transform and filter at once.', ['Iterate over dictionaries.','Keep only active records.','Extract each matching name.']),
      challenge('Train/test split (deterministic)','Write a simple function split_data(rows, train_ratio) that divides a list in original order. Explain why production ML should shuffle or stratify appropriately.',`[1,2,3,4,5], ratio 0.6 → [1,2,3] and [4,5]`, `def split_data(rows, train_ratio=0.8):\n    if not 0 <= train_ratio <= 1:\n        raise ValueError("Ratio must be between 0 and 1")\n    boundary = int(len(rows) * train_ratio)\n    return rows[:boundary], rows[boundary:]\n\nprint(split_data([1, 2, 3, 4, 5], 0.6))`, 'Use a slice index from int(len(rows) * ratio).', ['Validate the fraction.','Compute the split position.','Return two non-overlapping slices and note the ordering limitation.'], 'Intermediate'),
      challenge('Standardization basics','Given a nonempty numeric list, compute population mean and standard deviation and return z-scores. Handle the case of zero variance.',`[2,4,6] → approximately [-1.225,0,1.225]`, `def z_scores(values):\n    if not values:\n        return []\n    mean = sum(values) / len(values)\n    variance = sum((x - mean) ** 2 for x in values) / len(values)\n    std = variance ** 0.5\n    return [(x - mean) / std for x in values] if std else [0.0] * len(values)\n\nprint(z_scores([2, 4, 6]))`, 'Variance is the mean of squared distances from the mean.', ['Compute the mean.','Compute population variance and its square root.','Divide centered values by standard deviation, guarding zero.'], 'Intermediate')
    ], 'extended'),
  stage('projects','Mini-projects','Combine the concepts into realistic programs in VS Code.',
    'Projects reveal whether knowledge transfers beyond short exercises. Build real Python files, break work into functions, persist data where appropriate, and test edge cases. These are longer capstones; do not copy the solution architecture before attempting your own design.',
    `# Example project layout\nproject/\n  main.py\n  models.py\n  storage.py\n  tests/\n    test_logic.py\n  README.md`,
    ['Plan data structures before writing code.','Build one feature at a time.','Use functions for operations and tests for logic.','Write a README explaining how to run the project.'],
    'Do not build the full interface first. Make your core logic reliable, then add menus and persistence.',[
      challenge('Railway ticket manager','Build a terminal application that lists journeys, books a ticket, searches bookings, cancels tickets, and shows statistics. Use lists and dictionaries first; add JSON persistence as a second phase.',`Menu: 1 List journeys 2 Book 3 Search 4 Cancel 5 Statistics 0 Exit`, `# One possible starting architecture (extend in VS Code)\njourneys = [{"id": 1, "from": "Casablanca", "to": "Rabat", "seats": 3}]\nbookings = []\n\ndef book_ticket(journey_id, passenger):\n    journey = next((j for j in journeys if j["id"] == journey_id), None)\n    if journey is None or journey["seats"] <= 0:\n        return None\n    journey["seats"] -= 1\n    booking = {"id": len(bookings) + 1, "journey_id": journey_id, "passenger": passenger}\n    bookings.append(booking)\n    return booking\n\nassert book_ticket(1, "Ava")["passenger"] == "Ava"`, 'First create functions for booking, searching, and cancellation. Add the console menu last.', ['Define journeys and bookings as lists of dictionaries.','Implement book/search/cancel functions with validation.','Add menu-driven input, JSON save/load, and tests for no seats and missing IDs.'], 'Project'),
      challenge('Expense tracker','Create a terminal expense tracker that adds expenses, groups them by category, filters by date, and saves/loads expenses.json.',`add food 25 → list / category report → food: 25`, `# Starter architecture (complete the CLI, filters, and tests)\nimport json\nfrom pathlib import Path\n\nFILE = Path("expenses.json")\n\ndef load_expenses():\n    if not FILE.exists():\n        return []\n    return json.loads(FILE.read_text(encoding="utf-8"))\n\ndef add_expense(expenses, category, amount, date):\n    if amount < 0:\n        raise ValueError("Amount must be non-negative")\n    expenses.append({"category": category, "amount": amount, "date": date})\n\ndef save_expenses(expenses):\n    FILE.write_text(json.dumps(expenses, indent=2), encoding="utf-8")`, 'Split storage, business logic, and terminal interaction into functions.', ['Design one dictionary per expense.','Add safe JSON load/save and validation.','Implement summaries, filtering, the menu, and tests.'], 'Project'),
      challenge('Log file analyzer','Build a tool that parses log lines containing timestamp, severity, and message. Count each severity, list ERROR lines, and write a summary report.',`2026-10-01 ERROR Disk full → ERROR count 1`, `# Starter architecture (expand input format validation)\nfrom collections import Counter\nfrom pathlib import Path\n\ndef analyze_log(path):\n    severities = Counter()\n    errors = []\n    for line in Path(path).read_text(encoding="utf-8").splitlines():\n        parts = line.split(" ", 2)\n        if len(parts) != 3:\n            continue\n        timestamp, level, message = parts\n        severities[level] += 1\n        if level == "ERROR":\n            errors.append((timestamp, message))\n    return severities, errors\n\n# Add: report writer, CLI, tests for empty/malformed lines`, 'Start with one known input format and write test fixtures.', ['Define how a valid log line should look.','Parse, validate, and collect counters.','Create a report and test it on malformed input.'], 'Project'),
      challenge('Final assessment: Python foundations','Without viewing the solution, implement a small library manager. Users can add books, borrow and return them, search by title, and persist state in JSON. Include at least six automated tests.',`Borrow already-borrowed book → rejected; search missing title → []`, `# Reference design sketch, not a complete submission\nfrom dataclasses import dataclass\n\n@dataclass\nclass Book:\n    id: int\n    title: str\n    borrowed: bool = False\n\ndef borrow(book):\n    if book.borrowed:\n        raise ValueError("Book is already borrowed")\n    book.borrowed = True\n\n# Your work: add/search/return, JSON serialization,\n# terminal menu, error handling, and six tests.`, 'You should be able to design this from scratch using earlier sections.', ['Write a one-page design: data model, menu, and functions.','Implement features incrementally and persist with JSON.','Test happy paths, missing items, invalid requests, and repeated borrowing.'], 'Project')
    ], 'projects')
];

export const glossary = [
  ['Variable','A name bound to a value in memory.'], ['Expression','Code that evaluates to a value.'],
  ['Statement','An instruction Python executes.'], ['Type','The kind of data a value represents.'],
  ['Iterable','An object that can provide its elements one by one.'], ['Mutable','An object whose contents may change after creation.'],
  ['Immutable','An object that cannot be changed in place.'], ['Index','A zero-based location in a sequence.'],
  ['Slice','A way to select a range of elements from a sequence.'], ['Parameter','A name in a function definition.'],
  ['Argument','A value passed to a function when calling it.'], ['Return value','A value sent back to the function caller.'],
  ['Scope','The region of a program in which a name can be resolved.'], ['Exception','A runtime signal that an operation failed or was interrupted.'],
  ['Traceback','The chain of calls and source lines associated with an exception.'], ['Module','A Python source file that can be imported.'],
  ['Package','A collection of related Python modules.'], ['Virtual environment','An isolated Python interpreter and installed dependency context.'],
  ['Class','A template describing data and behavior of objects.'], ['Instance','An object created from a class.'],
  ['Comprehension','Concise syntax for producing collections from iterables.'], ['Big O','A description of how resource use grows with input size.'],
  ['Edge case','An unusual or boundary input that could expose a bug.'], ['Unit test','A small automated check of a unit of behavior.'],
  ['JSON','A text format for structured data exchange.'], ['CLI','Command-line interface, typically run from a terminal.'],
  ['List','A mutable ordered sequence in Python.'], ['Tuple','An immutable ordered sequence in Python.'],
  ['Dictionary','A mapping from hashable keys to values.'], ['Set','A collection of distinct hashable values.']
];
export const totalChallenges = stages.reduce((total, item) => total + item.challenges.length, 0);
export const coreCount = stages.filter(stage => stage.category === 'core').length;
